import 'reflect-metadata';
import { NestFactory } from '@nestjs/core';
import type { NextFunction, Request, Response } from 'express';
// @ts-ignore Generated by the backend build step before Vercel bundles this function.
import { AppModule } from '../backend/dist/app.module.js';
// @ts-ignore Generated by the backend build step before Vercel bundles this function.
import { configureApp } from '../backend/dist/common/bootstrap.config.js';
// @ts-ignore Generated by the backend build step before Vercel bundles this function.
import { getEnv, requireEnv, requireJwtRefreshSecret, maskConnectionString } from '../backend/dist/common/env.util.js';

type ExpressLikeHandler = (req: Request, res: Response) => unknown;

let cachedServer: ExpressLikeHandler | null = null;
let bootstrapError: string | null = null;

function sanitizeError(errStr: string | null): string | null {
  if (!errStr) return null;
  return maskConnectionString(errStr);
}

function assertRequiredEnvVars() {
  requireEnv('JWT_SECRET');
  requireJwtRefreshSecret();

  if (!getEnv('COOKIE_SECRET')) {
    console.warn('[bootstrap] ATENÇÃO: COOKIE_SECRET não configurada. Usando JWT_SECRET como fallback.');
  }

  if (!getEnv('RECAPTCHA_SECRET_KEY')) {
    console.warn('[bootstrap] ATENÇÃO: RECAPTCHA_SECRET_KEY não configurada.');
  }

  requireEnv('SUPABASE_URL', 'VITE_SUPABASE_URL');
  requireEnv('SUPABASE_ANON_KEY', 'VITE_SUPABASE_ANON_KEY');

  if (!getEnv('SUPABASE_SERVICE_ROLE_KEY', 'VITE_SUPABASE_SERVICE_ROLE_KEY')) {
    console.warn('[bootstrap] ATENÇÃO: SUPABASE_SERVICE_ROLE_KEY não configurada. Usando SUPABASE_ANON_KEY como fallback.');
  }

  // Validate DATABASE_URL separately with better error message
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl || !dbUrl.trim()) {
    const msg =
      'DATABASE_URL não configurada. Acesse o dashboard do Vercel e defina DATABASE_URL com a URL do Supabase PostgreSQL (pooler porta 6543).';
    console.error('[bootstrap] ERRO: ' + msg);
    console.error('[bootstrap] Dashboard: https://vercel.com/luccarellustech/eventease/settings/environment-variables');
    throw new Error(msg);
  }

  console.log('[bootstrap] DATABASE_URL:', maskConnectionString(dbUrl));

  // Validate URL format (must end with .supabase.com for Supabase)
  if (!dbUrl.includes('supabase.com') && !dbUrl.includes('localhost')) {
    console.warn('[bootstrap] ATENÇÃO: DATABASE_URL não parece ser do Supabase.');
    console.warn('[bootstrap] Formato esperado: postgresql://postgres.xxxx@aws-0-sa-east-1.pooler.supabase.com:6543/postgres?pgbouncer=true');
    console.warn('[bootstrap] Host atual detectado:', dbUrl.split('@')[1]?.split('/')[0] || '<desconhecido>');
  }

  console.log('[bootstrap] SUPABASE_URL definida:', !!process.env.SUPABASE_URL || !!process.env.VITE_SUPABASE_URL);
  console.log('[bootstrap] JWT_SECRET definida:', !!process.env.JWT_SECRET);
  console.log('[bootstrap] NODE_ENV:', process.env.NODE_ENV || 'não definido');
}

// Health check that works WITHOUT NestJS (for testing and debugging)
function handleHealthCheck(_req: Request, res: Response) {
  res.statusCode = 200;
  res.setHeader('Content-Type', 'application/json');
  return res.end(
    JSON.stringify({
      status: bootstrapError ? 'error' : 'ok',
      app: 'standalone',
      nestjs: !!cachedServer,
      ...(bootstrapError ? { detail: sanitizeError(bootstrapError) } : {}),
    })
  );
}

async function bootstrapServer(): Promise<ExpressLikeHandler | null> {
  if (!cachedServer) {
    try {
      console.log('[bootstrap] Verificando variáveis de ambiente...');
      assertRequiredEnvVars();

      console.log('[bootstrap] Criando aplicação NestJS...');
      const app = await NestFactory.create(AppModule);

      console.log('[bootstrap] Configurando aplicação (CORS, Helmet, cookies)...');
      (configureApp as unknown as (application: typeof app) => void)(app);

      // Middleware to remove the /api prefix before routing to NestJS controllers
      app.use((req: Request, _res: Response, next: NextFunction) => {
        if (req.url.startsWith('/api')) {
          req.url = req.url.substring(4) || '/';
        }
        next();
      });

      console.log('[bootstrap] Inicializando módulos (conectando ao banco)...');
      await app.init();

      cachedServer = app.getHttpAdapter().getInstance() as ExpressLikeHandler;
      bootstrapError = null;
      console.log('[bootstrap] Aplicação inicializada com sucesso!');
    } catch (error: unknown) {
      let errorMessage = 'Erro desconhecido ao inicializar a aplicação.';
      if (error instanceof Error) {
        errorMessage = error.message;
        console.error('[bootstrap] ERRO FATAL:', error.message);
        process.stderr.write(`[bootstrap] ERRO FATAL: ${error.message}\n`);
        process.stderr.write(`[bootstrap] STACK: ${error.stack?.split('\n').slice(0, 6).join('\n') || '(sem stack)'}\n`);
      } else {
        const errStr = String(error);
        errorMessage = errStr;
        console.error('[bootstrap] ERRO FATAL (não-Error):', errStr);
        process.stderr.write(`[bootstrap] ERRO FATAL: ${errStr}\n`);
      }
      bootstrapError = errorMessage;
      return null;
    }
  }
  return cachedServer;
}

export default async function handler(req: Request, res: Response) {
  // Handle /api/health without needing NestJS
  if (req.url === '/api/health') {
    return handleHealthCheck(req, res);
  }

  try {
    const server = await bootstrapServer();
    if (!server) {
      const cleanDetail = sanitizeError(bootstrapError) || 'Erro desconhecido ao inicializar o servidor.';
      res.statusCode = 503;
      res.setHeader('Content-Type', 'application/json');
      res.setHeader('Access-Control-Allow-Origin', '*');
      return res.end(
        JSON.stringify({
          statusCode: 503,
          message: 'Serviço temporariamente indisponível.',
          error: 'Service Unavailable',
          detail: cleanDetail,
          hint: 'Acesse https://eventease.olharjovem.org/api/health para verificar a integridade da aplicação ou confira as variáveis de ambiente no Dashboard da Vercel.',
        })
      );
    }
    return server(req, res);
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    console.error('[handler] Erro inesperado:', errorMessage);
    process.stderr.write(`[handler] Erro inesperado: ${errorMessage}\n`);

    const cleanError = sanitizeError(errorMessage);
    res.statusCode = 500;
    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Access-Control-Allow-Origin', '*');
    return res.end(
      JSON.stringify({
        statusCode: 500,
        message: 'Erro interno do servidor.',
        error: 'Internal Server Error',
        detail: cleanError,
      })
    );
  }
}
